  "onb.profile.desc": "Harness Maxxing ist kostenlos und braucht kein Konto. Du kannst uns trotzdem sagen, wer du bist: Alles auf dieser Seite ist optional.",
  "onb.profile.pseudoDesc": "Dein Pseudonym in Harness Maxxing (in den Telegram-Kopien deiner Nachrichten). Änderbar unter Einstellungen → Profil.",
  "onb.profile.counterOn": "Wird an api.harness-maxxing.com gesendet. Dein Pseudonym und deine Sprache werden nur mit einer E-Mail gesendet. Ein anonymer Zähler (Version, System, Gesundheitscodes; kein Name, keine IP) ist standardmäßig aktiv: Du kannst ihn unter Einstellungen → Profil ausschalten.",
  "register.desc": "Alles ist optional. Was dieser Server den Autoren von Harness Maxxing mitteilt und wie du es stoppst.",
