  "register.emailPlaceholder": "du@beispiel.de",
  "register.emailDesc": "Nur um dich vor einem Sicherheitsproblem oder einer größeren Änderung zu warnen. Nie weitergegeben, nie verkauft.",
  "register.emailInvalid": "Das sieht nicht nach einer E-Mail-Adresse aus.",
  "register.news": "Schick mir auch die Neuigkeiten zum Produkt",
  "register.newsDesc": "Neue Funktionen, höchstens ein paar Mal im Monat. Du kannst dich hier jederzeit abmelden.",
  "register.count": "Beim Zählen der Installationen helfen (anonym)",
  "register.countDesc": "Einmal am Tag: eine Zufallszahl, die Version, das System (z. B. Ubuntu 24.04, x86_64) und ein paar Gesundheitscodes (Dienst aktiv, Claude angemeldet, letztes Update fehlgeschlagen …). Kein Name, keine E-Mail, keine IP, kein Servername, keine Inhalte.",
  "register.countBlocked": "Auf diesem Server durch MAXXING_NO_TELEMETRY oder DO_NOT_TRACK in der Dienstumgebung deaktiviert.",
  "register.privacy": "Wird an api.harness-maxxing.com gesendet. Dein Pseudonym und deine Sprache werden nur mit einer E-Mail gesendet. Wenn du alles abwählst, wird nichts mehr gesendet: Wir kontaktieren diesen Server nie wieder.",
  "register.statusOff": "Dieser Server teilt den Autoren nichts mit.",
