  "register.stop": "Stopp, nicht mehr kontaktieren",
  "donation.title": "Harness Maxxing unterstützen",
  "donation.desc": "Kostenlos für alle, ohne Werbung, ohne Tracking.",
  "donation.body": "Harness Maxxing ist kostenlos und der Code ist öffentlich. Wenn es dir Zeit spart, hilft uns eine Spende, es weiter zu verbessern. Der Button öffnet unsere Website in einem neuen Tab; aus dieser App wird nichts gesendet.",
