  "claude.removeTitle": "Gespeicherten Token oder Schlüssel entfernen?",
  "claude.removeDesc": "Sitzungen funktionieren nicht mehr, bis du Claude erneut verbindest.",
  "claude.tabSubscription": "Claude-Abo",
  "claude.tabApiKey": "API-Schlüssel",
  "claude.subscriptionIntro": "Empfohlen mit einem Pro-, Max- oder Ultra-Tarif. Erzeuge von diesem Server aus ein langlebiges Token (Claude Code ist dort bereits installiert):",
  "claude.step1": "Öffne ein Terminal auf dem Server (SSH):",
  "claude.step2": "Führe diesen Befehl aus, öffne den angezeigten Link, melde dich mit deinem Claude-Konto an und autorisiere den Zugriff. Füge dann den Code wieder ins Terminal ein:",
  "claude.step3": "Kopiere das angezeigte Token (es beginnt mit sk-ant-oat) und füge es unten ein.",
  "claude.apiKeyIntro": "Abrechnung nach Verbrauch über die Anthropic Console statt eines Abos.",
  "claude.apiStep1": "Erstelle einen Schlüssel unter",
  "claude.apiStep2": "Kopiere ihn (er beginnt mit sk-ant-api) und füge ihn unten ein.",
  "claude.tokenLabel": "Token",
  "claude.keyLabel": "API-Schlüssel",
  "claude.storedHint": "Wird nur auf diesem Server gespeichert (Secrets-Datei, nur für root lesbar) und nie wieder angezeigt.",
  "claude.pasteFirst": "Füge zuerst das Token ein.",
  "claude.authFailed": "Claude hat diese Zugangsdaten abgelehnt.",
  "claude.connectTest": "Verbinden und testen",
  "claude.testing": "Testnachricht an Claude wird gesendet…",
  "cdef.defaultModel": "Standardmodell",
  "cdef.cliDefault": "Standard von Claude Code",
  "cdef.defaultModelHint": "Sitzungen zeigen das Modell an, das jeden Durchlauf tatsächlich beantwortet hat.",
  "cdef.autoCompact": "Automatische Komprimierung",
  "cdef.autoCompactHint": "Endet ein Durchlauf mit mehr Kontext als diesem Wert, fasst Harness die Sitzung zusammen und macht in einem neuen Verlauf weiter, der mit der Zusammenfassung beginnt (wie Komprimieren): Lange Sitzungen senden nicht mehr ihren ganzen Verlauf erneut, das spart Tokens. Der Verlauf bleibt sichtbar.",
  "cdef.autoCompactOff": "Aus",
  "cdef.autoCompactRecommended": "empfohlen",
  "cdef.idleCompact": "Beim Zurückkommen komprimieren",
  "cdef.idleCompactHint": "Der Prompt-Cache von Claude hält ein paar Minuten (höchstens eine Stunde). Schreibst du in eine Sitzung, die länger inaktiv war und mindestens so viel Kontext hat, fasst Harness sie zuerst zusammen, und deine Nachricht läuft in einem neuen Verlauf, der mit der Zusammenfassung beginnt: Der Verlauf würde ohnehin zum vollen Preis erneut gesendet, spätere Durchläufe werden so viel günstiger. Kostet einen Zusammenfassungs-Durchlauf (kurze Wartezeit) vor der Antwort.",
  "cdef.smartResume": "Intelligentes Fortsetzen",
  "cdef.smartResumeHint": "Kommst du zu einer Sitzung zurück, deren Cache abgelaufen ist (siehe oben) und die mindestens so viel Kontext hat, oder nach 5 Minuten oder mehr bei doppelt so viel, lässt Harness Claude die Sitzung zuerst passend zu der Nachricht zusammenfassen, die du gerade gesendet hast: Die Zusammenfassung behält genau das, was deine Nachricht braucht (Dateien, Befehle, Werte, den laufenden Plan), und deine Nachricht läuft dann in einem neuen, deutlich kleineren Verlauf. An echten Wiedereinstiegen gemessen: 38 bis 67 % weniger Tokens ab 100k und besser erhaltene Details als bei der einfachen Zusammenfassung. Aus = nur die Regel oben.",
  "cdef.protectSecrets": "Geheimnisse schützen",
  "cdef.protectSecretsHint": "Die Tools von Claude weigern sich, die Geheimnisse des Servers (secrets.json) und die SSH-Schlüssel (~/.ssh) zu lesen oder zu ändern, unabhängig vom Berechtigungsmodus. So kann eine in einer Webseite oder E-Mail versteckte Anweisung sie nicht einfach lesen; ein Skript, das die Datei öffnet, wird nicht gestoppt - bei Inhalten von außen wähle für dieses Thema lieber einen strengeren Berechtigungsmodus.",
  "cdef.shortTitles": "Kurze Sitzungstitel",
  "cdef.shortTitlesHint": "Eine neue Sitzung wird anhand ihrer ersten Nachricht in wenigen Wörtern benannt (ohne Begrüßungen und „kannst du…“). Aus: Der Titel ist der Anfang der Nachricht. Eine manuelle Umbenennung hat immer Vorrang.",
  "cdef.shortTitlesModel": "Von Claude geschriebene Titel",
  "cdef.shortTitlesModelHint": "Das kleinste Modell benennt das Thema (treffendere Titel). Ein kurzer Aufruf pro neuer Sitzung, wird auf deinen Claude-Tarif angerechnet.",
  "pbox.mode": "Sandbox (nur dieses Thema)",
  "pbox.modeDesc": "Claude arbeitet frei im Ordner des Themas, ohne zu fragen: Seine Befehle schreiben nur dort und können weder die Schlüssel des Servers noch den Home-Ordner lesen. Was darüber hinausgeht (ein Paket installieren, einen Dienst neu starten, ein anderer Ordner), wird zuerst bei dir erfragt, mit einem Button, der dem Thema vollen Zugriff gibt.",
  "cdef.autoUpdate": "Claude Code automatisch aktualisieren",
  "cdef.autoUpdateHint": "Standardmäßig aus. An: Erscheint eine neuere stabile Version von Claude Code (eine, die schon einige Tage im Einsatz ist, nicht die allerneueste), installiert der Server sie, sobald 10 Minuten nichts gelaufen ist (kein Durchlauf, keine Nachricht in der Warteschlange, kein geplanter Job), und kehrt zur vorherigen zurück, falls sie nicht startet. Prüfung alle 6 Stunden; das Ergebnis erscheint in den Benachrichtigungen.",
  "cdef.autoUpdateLast": "Letztes Update: {from} → {to}, {date}",
  "cdef.autoUpdateFailed": "Update auf {to} fehlgeschlagen ({date})",
  "claude.permissionMode": "Berechtigungsmodus",
  "claude.mode.bypass": "Voller Zugriff (Berechtigungen umgangen)",
  "claude.mode.bypassDesc": "Claude führt jeden Befehl aus und ändert jede Datei, ohne zu fragen, mit den Rechten des Dienstbenutzers (root). Wähle das nur, wenn dieser Server Claude vorbehalten ist.",
  "claude.mode.recommendedVps": "Nur dedizierter VPS",
  "claude.mode.acceptEdits": "Dateiänderungen akzeptieren",
  "claude.mode.acceptEditsDesc": "Claude kann Dateien lesen und schreiben; andere Tools, die eine Freigabe brauchen (die meisten Shell-Befehle), werden abgelehnt.",
  "claude.mode.default": "Strikt (ablehnen)",
  "claude.mode.defaultDesc": "Jedes Tool, das eine Freigabe braucht, wird ohne Nachfrage abgelehnt. Am sichersten, aber Claude kann deutlich weniger.",
  "claude.mode.ask": "Mich fragen",
  "claude.mode.askDesc": "Lesen ist frei; alles andere wartet auf dein Erlauben oder Ablehnen, in der Sitzung, in den Benachrichtigungen oder in Telegram. Nach 30 Min ohne Antwort abgelehnt.",
  "claude.mode.note": "Außer bei „Mich fragen“ wird niemand gefragt: Alles, was der Modus nicht erlaubt, wird einfach abgelehnt.",
  "telegram.setup": "Telegram einrichten",
  "telegram.setupDesc": "Etwa zwei Minuten. Du brauchst die Telegram-App auf deinem Smartphone oder Computer.",
