  "telegram.scan": "Mit dem Handy scannen",
  "telegram.openAndStart": "Öffne den Bot und tippe auf Start. Diese Seite aktualisiert sich von selbst, sobald die Verknüpfung steht.",
  "telegram.openTelegram": "In Telegram öffnen",
  "telegram.waiting": "Warte auf /start…",
  "telegram.manualCode": "Oder sende diese Nachricht an den Bot:",
  "telegram.chatLinked": "Chat verknüpft",
  "telegram.simpleIntro": "Ein einziger Chat zum Verfolgen: Schreibe eine Nachricht, um eine Sitzung zu starten (der Bot fragt, in welchem Thema), antworte auf eine Nachricht, um ihre Sitzung fortzusetzen. Die Warnungen kommen auch dort an. Stattdessen ein Thread pro Sitzung: Einstellungen › Telegram › Modus.",
  "telegram.threadsIntro": "Jede offene Sitzung bekommt ihren eigenen Thread (dazu Crons und Warnungen). Archivierst du eine Sitzung, verschwindet ihr Thread; schreibe im Haupt-Chat, um eine neue zu starten.",
  "telegram.created": "{count} Threads erstellt",
