  "mcp.whatTitle": "MCP-Server geben Claude neue Werkzeuge",
  "mcp.whatExplain": "Ein Server, der für „Jede Sitzung“ hinzugefügt wurde, ist überall verfügbar; wird er einem Thema hinzugefügt, nur in den Sitzungen dieses Themas. Geheimnisse bleiben in Einstellungen → Schlüssel und werden als ${KEY_NAME} referenziert. Du kannst auch einfach Claude in einem Thema fragen: „verbinde den MCP …“.",
