  "mcp.autoHint": "Jeder geladene Server kostet bei jeder Nachricht Tokens und verlangsamt den Start eines Durchlaufs. Wenn aktiviert, bekommt eine Sitzung die Server, die ihr Thema schon genutzt hat, die in deiner Nachricht genannten und die, die ihrem Thema hinzugefügt wurden; Claude kann einen weiteren anfordern (`maxxing mcp load`) und Harness macht von selbst weiter. Wird ein claude.ai-Connector benötigt, wird wie bisher alles geladen. Die Werkzeuge des Harness-Browsers und deiner Geräte sind immer da, wenn ein Durchlauf sie nutzen kann.",
