  "mcp.step3": "Du landest auf einer Fehlerseite: Das ist normal",
  "mcp.step3Desc": "Der Dienst leitet dich auf eine Adresse des Harness-Servers (\"localhost\") weiter, die dein Browser nicht öffnen kann, daher zeigt er \"Diese Website ist nicht erreichbar\". Die Verbindung ist noch nicht abgeschlossen: Der Code steckt in der Adresse.",
  "mcp.browserError": "Diese Website ist nicht erreichbar - localhost hat die Verbindung abgelehnt.",
  "mcp.step3Copy": "Kopiere die gesamte Adresse aus der Adressleiste (klicke darauf, dann Ctrl+C / ⌘C). Auf dem Handy: Adresse lange gedrückt halten, Kopieren.",
  "mcp.step4": "Komm hierher zurück und füge sie ein",
  "mcp.paste": "Einfügen",
  "mcp.pasteDenied": "Der Browser hat das abgelehnt: Füge sie mit Ctrl+V / ⌘V in das Feld ein.",
  "mcp.noCode": "Diese Adresse enthält kein \"code=\": Kopiere nach dem Akzeptieren die Adresse der Fehlerseite.",
  "mcp.whyTitle": "Warum dieses Kopieren und Einfügen?",
  "mcp.whyBody": "Claude Code, das auf deinem Server läuft, wartet auf die Antwort des Dienstes an einer lokalen Adresse des Servers. Der Dienst kann deinen Browser nur an diese Adresse zurückschicken, die nur auf dem Server existiert. Indem du sie einfügst, gibst du den Code an Claude Code weiter, das die Verbindung abschließt. Das funktioniert bei jedem Zugang (Domain, Tailscale) und braucht nichts weiter. Mach es innerhalb weniger Minuten: Der Code läuft ab.",
  "mcp.finish": "Abschließen",
