  "keys.exposeDesc": "Wird bei jedem Harness-Durchlauf als Umgebungsvariable exportiert. Erweiterungen lesen Schlüssel auch ohne das: Lass es deaktiviert, außer Sitzungen brauchen die Variable.",
  "keys.exposeTitle": "Bereitgestellte Schlüssel",
  "keys.exposeExplain": "Ein bereitgestellter Schlüssel steht Harness als Umgebungsvariable (z. B. $OPENAI_API_KEY) in jeder Sitzung und jedem Cron zur Verfügung, sodass Skripte ihn nutzen können, ohne dass der Wert in einem Prompt auftaucht. Harness kann ihn trotzdem lesen: Stelle nur bereit, was Sitzungen brauchen.",
