  "keyfiles.safety": "Sichere Speicherung: Die Dateien bleiben außerhalb des Backups, von Git und von Gedächtnisdateien, und nichts auf dieser Seite erlaubt es, sie wieder auszulesen. Das ist keine Isolation gegenüber einer Sitzung: Sitzungen laufen mit demselben Benutzer wie der Server, daher kann eine Sitzung, der der Pfad gegeben wird, die Datei lesen.",
