  "infra.how.create": "Sag in jeder Sitzung, was du willst: Claude nutzt die Standardrezepte (eine Website hinter Caddy mit HTTPS, eine PostgreSQL-Datenbank mit nächtlichem Backup, ein S3-Bucket) und das Neue erscheint hier. Öffne eine beliebige Zeile, um Details zu sehen oder Claude dazu zu fragen.",
  "infra.how.createTitle": "Du erstellst, indem du Claude fragst",
  "infra.how.watch": "Jede Adresse wird geprüft (antwortet sie, ist ihr Zertifikat gültig), ebenso das Ablaufdatum der Domains und der Speicherplatz. Ein Problem erscheint oben auf dieser Seite und in deinen Benachrichtigungen, einmal pro Vorfall.",
  "infra.how.watchTitle": "Es überwacht für dich",
  "infra.how.read": "Diesen Server direkt, deine anderen Server per SSH (nur lesend) sowie Cloudflare und Hostinger mit ihren API-Schlüsseln. Es listet jede Website, Datenbank, jeden Bucket, jede Domain und jeden Server auf und verknüpft sie miteinander (eine Domain mit ihrer Website, eine Website mit ihrer App, ihrer Datenbank und ihrem Git-Repository).",
