  "infra.mail.f.spf_neutral": "Beende ihn mit ~all (oder -all).",
  "infra.mail.p.dmarc_inherited_sp": "Kein DMARC-Eintrag für {domain}: {parent} setzt sp=none für seine Subdomains, daher erhält {domain} p=none, unabhängig vom p= von {parent}.",
  "infra.mail.f.dmarc_inherited_sp": "Sobald SPF und DKIM für {domain} bestehen, ändere sp=none im Eintrag von {parent} auf sp=quarantine und dann auf sp=reject, oder gib {domain} einen eigenen Eintrag _dmarc.{domain} mit p=quarantine. Senke das p= von {parent} nicht.",
  "infra.mail.p.dmarc_inherited_sp_quarantine": "Kein DMARC-Eintrag für {domain}: {parent} setzt p={parent_policy}, aber sp={policy} für seine Subdomains, daher erhält {domain} p={policy}.",
  "infra.mail.f.dmarc_inherited_sp_quarantine": "Damit {domain} ebenfalls p={parent_policy} erhält, ändere sp={policy} im Eintrag von {parent} auf sp={parent_policy} (oder entferne sp=), oder gib {domain} einen eigenen Eintrag _dmarc.{domain} mit p={parent_policy}. Senke das p= von {parent} nicht.",
