  "infra.mail.f.dmarc_parent_invalid": "Korrigiere den Eintrag _dmarc.{parent} (ein einziger TXT-Eintrag v=DMARC1 mit einem p=), oder füge einen TXT-Eintrag _dmarc.{domain} hinzu: {record}",
