  "infra.mail.f.no_spf_sender": "Füge auf {domain} einen TXT-Eintrag hinzu, der jeden Dienst nennt, über den du sendest: Starte mit {record} und ergänze vor ~all das include: von {sender} (dein Anbieter dokumentiert es).",
  "infra.mail.p.no_spf_unknown": "Kein SPF-Eintrag: Jeder kann behaupten, Mails als @{domain} zu senden.",
  "infra.mail.f.no_spf_unknown": "Füge auf {domain} einen TXT-Eintrag hinzu, der jeden Dienst nennt, über den du Mails sendest. Allein aus den MX-Einträgen wäre es {record}: Ergänze vor ~all das include: des Dienstes, über den du sendest (dein Mail-Anbieter dokumentiert es), sonst besteht deine gesendete Mail die SPF-Prüfung nicht.",
