  "system.cpuPrioritiesDesc": "Wenn der Prozessor ausgelastet ist, hat das, was du gerade ansiehst, Vorrang; schwere Arbeiten (Renderings, geplante Jobs) werden etwas langsamer, aber nie gestoppt.",
