  "system.cleanup": "Platz freigeben",
  "system.cleanupClaude": "Mit Claude aufräumen",
  "system.cleanupDesc": "Nur, was von selbst wiederkommt oder was du auswählst. Projekte, Anhänge und Renderings bleiben: „Mit Claude aufräumen“ sieht sie sich gemeinsam mit dir an.",
  "system.cleanupScanning": "Wird gemessen…",
