  "system.cleanup.leftovers": "Alte Versionen und Überreste",
  "system.cleanup.leftoversDesc": "Frühere Versionen der Komponenten, nicht mehr genutzte Browser, temporäre Dateien, zu große Logs.",
  "system.cleanup.caches": "Download-Caches",
  "system.cleanup.cachesDesc": "uv-, npm-, pip- und npx-Caches: Werden beim nächsten Bedarf erneut heruntergeladen. Was ein laufendes Tool nutzt, bleibt.",
  "system.cleanup.journal": "Systemlogs",
  "system.cleanup.journalDesc": "Das systemd-Journal, gekürzt auf die letzten 200 MB.",
  "system.cleanup.apt": "Heruntergeladene Systempakete",
  "system.cleanup.aptDesc": "Pakete, die das System bereits installiert hat (der Cache von apt, dnf oder pacman).",
  "system.cleanup.previews": "Videovorschauen und Vorschaubilder",
  "system.cleanup.previewsDesc": "Leichtere Kopien von Videos für den Player und Vorschaubilder von Dateien: Werden beim Anzeigen neu erstellt (etwas Rechenleistung). Ein Video, das in den letzten 30 Min. abgespielt wurde, bleibt.",
  "system.cleanup.trash": "Papierkorb von Harness",
  "system.cleanup.trashDesc": "Gelöschte Themen, Sitzungen und Dateien: Sie können danach nicht mehr wiederhergestellt werden.",
  "system.cleanupPrompt": "Prüfe den Speicherplatz dieses Servers und hilf mir, ihn sauber freizugeben.\n\n1. Zustand: `df -h` und `free -h`, dann die größten Ordner (`du -xh --max-depth=2 / 2>/dev/null | sort -h | tail -40`), und sieh dir die größten genauer an. Einstellungen → System → Platz freigeben kümmert sich bereits um die Download-Caches, alte Komponentenversionen, das Systemjournal, apt-Pakete, Videovorschauen und den Papierkorb von Harness: Lass diese beiseite.\n2. Gehe jedes Projekt und Thema des Arbeitsbereichs durch: Anhänge, Video- und Audio-Renderings, Exporte, `node_modules`, Python-Umgebungen, Builds, große Git-Repositories, vergessene separate Kopien, Duplikate. Sieh dir auch die Caches anderer Tools an (`~/.cache/*`, heruntergeladene Modelle), Logs und alte Dateien in `/tmp`.\n3. Finde für jedes große Element heraus, woher es kommt: welches Projekt, welches Tool oder welcher geplante Job es erstellt hat (Daten, Inhalt, Gedächtnis des Themas, Crons) und ob es noch wächst.\n4. Gib mir eine nach Größe sortierte Tabelle: Pfad, Größe, Herkunft, kommt von selbst wieder oder nicht, dein Vorschlag (löschen, anderswohin verschieben, behalten) und der gewonnene Platz.\n5. Lösche nichts ohne mein OK: Stell mir alle deine Fragen auf einmal. Schlage bei dem, was ständig wiederkommt, vor, die Ursache zu beheben (ein Größenlimit, eine Bereinigung im Skript oder Job, der es erzeugt).\n6. Halte am Ende im Gedächtnis des passenden Themas fest, was wir beschlossen haben (was bleibt, was aufgeräumt wird).",
