  "vmode.cardDesc": "Sprich laut mit Harness: Eine Stimme antwortet dir, übergibt die eigentliche Arbeit mit deinen eigenen Worten an die Sitzung (dasselbe Claude, dieselben Dateien und Tools) und sagt dir das Ergebnis. Schaltfläche in der Leiste einer Sitzung.",
