  "vmode.set.cloud": "Cloud (Echtzeit)",
  "vmode.set.cloudDesc": "Ein Echtzeit-Sprachmodell von OpenAI oder Gemini: antwortet in unter einer Sekunde, klingt natürlich, du kannst ihm ins Wort fallen. Etwa 1 bis 5 Cent pro Minute über deinen Schlüssel; das Audio geht an diesen Anbieter.",
