  "pwa.steps.edge.2": "Kein Symbol? Öffne das Menü … → Apps → Diese Website als App installieren.",
  "pwa.steps.edge.3": "Klicke auf Installieren: Die App öffnet sich in einem eigenen Fenster, mit ihrem Symbol in der Taskleiste oder im Dock.",
  "pwa.steps.safari.1": "Wähle in der Menüleiste Ablage → Zum Dock hinzufügen (oder die Teilen-Schaltfläche → Zum Dock hinzufügen). Erfordert macOS 14 Sonoma oder neuer.",
  "pwa.steps.safari.2": "Klicke auf Hinzufügen: Die App öffnet sich aus dem Dock in einem eigenen Fenster.",
