  "settings.memory": "Gedächtnis",
  "settings.memory.desc": "Bereinigung des zweiten Gehirns: Größenlimit für memory.md und Aufräumen",
  "notify.title": "In diesem Browser",
  "notify.desc": "Lass dich benachrichtigen, wenn eine Antwort bereit ist, auch aus einem anderen Tab oder einer anderen App, und lege fest, wie ungelesene Antworten angezeigt werden. In diesem Browser gespeichert.",
  "notify.done": "Benachrichtige mich, wenn eine Sitzung fertig ist",
  "notify.doneDesc": "Systembenachrichtigung, wenn der Tab im Hintergrund ist, sonst ein kleines Banner. Geplante Jobs lösen keine Benachrichtigung aus.",
  "team.notifySetting": "Team-Nachrichten",
  "team.notifySettingDesc": "Eine neue Nachricht aus einem Team-Chat, der nicht auf dem Bildschirm ist, erscheint in einem Popup zum Antworten oder als Systembenachrichtigung, wenn Harness im Hintergrund ist (stummgeschaltete Chats benachrichtigen nie).",
  "features.agentPreview": "Vorschau beim Darüberfahren",
  "features.agentPreviewDesc": "Wenn du den Mauszeiger auf einem Agenten in einer Liste ruhen lässt, siehst du, was er gerade tut. Mit der Übersicht in Space zeigt die Karte auch seinen Raum.",
  "team.bubblesSetting": "Team-Bubbles",
  "team.bubblesSettingDesc": "Chats öffnen sich als Bubbles unten rechts auf jeder Seite, wie bei Messenger. Aus: Team öffnet eine eigene Seite.",
  "notify.sound": "Ton abspielen",
  "notify.soundDesc": "Ein kurzer, sanfter Klang bei jeder Benachrichtigung.",
  "notify.test": "Testen",
  "notify.testBody": "Benachrichtigungen funktionieren in diesem Browser.",
  "push.title": "Mobile Benachrichtigungen",
  "push.desc": "Erhalte „Harness ist fertig“ auf diesem Handy oder Computer, auch wenn die App geschlossen ist. Die Benachrichtigung enthält nur den Sitzungstitel und den Anfang der Antwort und wird von deinem eigenen Server gesendet.",
  "push.here": "Auf diesem Gerät benachrichtigen",
  "push.hereDesc": "Fragt den Browser nach der Erlaubnis und registriert dieses Gerät. Jeder abgeschlossene Durchlauf deiner Sitzungen meldet sich dann hier, außer dem, den du gerade ansiehst.",
  "push.feed": "Aus den Benachrichtigungen",
  "push.feedDesc": "Was auch auf den registrierten Geräten klingelt. Eine Anfrage, die auf dein OK wartet, kommt mit Erlauben und Ablehnen in der Benachrichtigung (Android und Computer; auf dem iPhone öffnest du sie mit einem Tipp). Warnungen sind die Hinweise und die Fehler: ein fehlgeschlagener Job, eine ungewöhnliche Ausgabe, eine Website, die nicht erreichbar ist.",
  "push.feed.all": "Anfragen und Warnungen",
  "push.feed.asks": "Nur Anfragen",
  "push.feed.off": "Nichts",
  "push.test": "Test senden",
  "push.testSent": "Test gesendet: Er sollte in wenigen Sekunden ankommen.",
  "push.testNone": "Der Test konnte an kein Gerät gesendet werden.",
  "push.denied": "Benachrichtigungen sind für diese Website blockiert: Erlaube sie in den Browser-Einstellungen und versuche es dann erneut.",
  "push.noWorker": "Die App ist noch nicht bereit für Benachrichtigungen: Lade die Seite neu und versuche es erneut.",
  "push.unsupported": "Dieser Browser kann keine Benachrichtigungen empfangen, wenn die App geschlossen ist. Nutze auf Android Chrome, am Computer Chrome, Edge oder Firefox (HTTPS erforderlich).",
  "push.install": "Füge die App auf dem iPhone und iPad zuerst zum Home-Bildschirm hinzu (Teilen, dann Zum Home-Bildschirm) und öffne sie dann von dort, um dies zu aktivieren.",
