  "notify.blocked": "Benachrichtigungen sind blockiert",
  "notify.blockedDesc": "Dein Browser blockiert Benachrichtigungen für diese Website: Erlaube sie in den Website-Einstellungen (Schloss-Symbol in der Adressleiste) und lade dann neu.",
  "notify.unsupported": "Dieser Browser hat keine Systembenachrichtigungen: Du bekommst das Banner in der App und den Ton.",
