  "memory.title": "Bereinigung des zweiten Gehirns",
  "memory.desc": "Hält jede memory.md kurz und gut geordnet: Duplikate werden zusammengeführt, Widersprüche aufgelöst, alter Verlauf zusammengefasst, Abschnitte sortiert. Läuft jede Nacht (Job „Memory compaction“) und auf Abruf.",
  "memory.cleanNow": "Jetzt aufräumen",
  "memory.limit": "Maximale Länge pro Datei",
  "memory.limitDesc": "Längere oder schwerere Dateien (1 KB für 10 Zeilen: 100 Zeilen = 10 KB) werden komprimiert und neu organisiert, damit sie darunter passen (etwa 80 %, um Spielraum zu lassen). Eine Gedächtnisdatei wird bei jeder Änderung vollständig erneut an Claude gesendet: Eine kurze kostet weniger und Sitzungen werden seltener zusammengefasst.",
