  "stats.budget": "Tagesbudget",
  "stats.budgetDesc": "Eine Obergrenze in Dollar pro Tag für den ganzen Server, zum Preis, den Claude Code für jeden Durchlauf angibt (bei einem Abo: was dieselben Durchläufe mit einem API-Schlüssel kosten würden).",
  "stats.budgetField": "Budget pro Tag ($)",
  "stats.budgetFieldDesc": "0 = kein Budget. Eine Benachrichtigung bei 80 %, ein Alarm bei Erreichen. Danach warten geplante Jobs und Agents bis morgen; deine eigenen Nachrichten und „Jetzt ausführen“ laufen weiterhin.",
