  "pr.reviewPrompt": "Prüfe die Pull Request #{n} \"{title}\" von {repo}: Ihr Branch ist dieser Ordner, vergleiche ihn mit `origin/{base}` (`git diff origin/{base}...HEAD`). Ändere keine Datei und veröffentliche nichts. Suche nach Bugs, riskantem Code und dem, was fehlt (Tests, Doku). Beende deine Antwort mit einem ```pr-review-Block mit JSON: {\"repo\": \"{repo}\", \"number\": {n}, \"event\": \"COMMENT\" | \"APPROVE\" | \"REQUEST_CHANGES\", \"summary\": \"…\", \"comments\": [{\"path\": \"…\", \"line\": <line in the new version>, \"body\": \"…\"}]}. Ich lese es und veröffentliche es.",
