  "term.setting": "Code-Modus",
  "term.settingDesc": "Zum Arbeiten am Code mit Claude: eine separate Kopie pro Sitzung (mit eigenem Branch und Ordner, abgeschlossen durch eine Pull Request, die Claude schreibt und überwacht) und ein Terminal unter der Unterhaltung (Ctrl+J, /terminal), geöffnet in den Git-Repositories der Sitzung. Die Änderungen jeder Antwort (Diff, Commit, Push, Pull Request) und die Pull-Request-Ansicht werden auch ohne ihn angezeigt. Nie für Agenten. Zum Aktivieren wird dein Passwort abgefragt.",
  "term.enableTitle": "Code-Modus aktivieren",
  "term.enableDesc": "Der Code-Modus fügt ein Terminal hinzu, das jeden Befehl auf diesem Server mit dessen Rechten ausführt, sowie separate Kopien eines Repositorys für Sitzungen. Gib zur Bestätigung dein Passwort ein.",
