  "show.cpu.title": "CPU-Prioritäten",
  "show.cpu.body": "Wenn der Prozessor ausgelastet ist, kommt zuerst das dran, was du dir ansiehst: die Oberfläche, dann deine Sitzungen; Renderings und geplante Jobs werden etwas langsamer, halten aber nie an. Klicke hier auf die CPU-Anzeige, um zu sehen, wer den Prozessor beansprucht. Zum Ausschalten: Einstellungen → System.",
  "show.code.title": "Code in einer Sitzung",
  "show.code.body": "Wenn Claude ein Git-Repository ändert, zeigt ein Button unter seiner Antwort die Änderungen: den Diff prüfen, eine Datei rückgängig machen, committen, pushen oder eine Pull Request öffnen. Rechtsklick auf deine Nachricht, um zu dem Stand davor zurückzukehren. Hier unter Sitzungen fügt der Code-Modus pro Sitzung eine separate Kopie und ein Terminal (Ctrl+J) hinzu.",
  "browser.title": "Browser",
  "browser.menu": "Browser…",
  "browser.sectionDesc": "Ein Chromium auf diesem Server für Websites ohne API: Er öffnet Seiten, klickt und füllt Formulare aus. Er wird nur verwendet, wenn eine Seite ihn braucht.",
  "browser.topicTitle": "Harness Browser · {name}",
  "browser.topicDesc": "Für die Sitzungen dieses Themas: Dürfen sie den Harness Browser verwenden (mit dem Profil des Projekts: seinen Anmeldungen und seiner Verbindung)? Claude liest Seiten zuerst mit einfacheren Werkzeugen.",
