  "nav.jarvis": "Jarvis",
  "features.page.jarvis": "Ein einziger Assistent, mit dem du sprichst: Er legt Projekte und Themen an, übergibt die Arbeit an Sitzungen und Agents, holt deren Ergebnisse ab und führt das Gespräch weiter – mit einem Morgenbriefing und einem Gedächtnis, das er jede Nacht aufräumt.",
  "jarvis.off.title": "Jarvis ist aus",
