  "jarvis.set.dreamNow": "Nachtlauf jetzt",
  "features.need.jarvis": "Verbraucht mehr von deinem Claude-Tarif als reine Sitzungen: Jede Antwort, die aus einer Sitzung zurückkommt, ist ein zusätzlicher Jarvis-Durchlauf, dazu kommen ein Morgenbriefing und ein Nachtlauf (Sonnet, an ruhigen Tagen übersprungen). Schalte das Briefing oder den Nachtlauf in seinen Einstellungen aus, um weniger zu verbrauchen.",
